class Node {
  constructor(value) {
    this.value = value;
    this.next = null;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
    this.tail = null; // tail pointer for O(1) append
    this.size = 0;
  }

  // O(1) — update head pointer only
  prepend(value) {
    const node = new Node(value);
    node.next = this.head;
    this.head = node;
    if (!this.tail) this.tail = node;
    this.size++;
  }

  // O(1) — tail pointer avoids full traversal
  append(value) {
    const node = new Node(value);
    if (!this.head) { this.head = this.tail = node; this.size++; return; }
    this.tail.next = node;
    this.tail = node;
    this.size++;
  }

  // O(n) — must walk to position
  insertAt(index, value) {
    if (index === 0) return this.prepend(value);
    const node = new Node(value);
    let cur = this.head;
    for (let i = 0; i < index - 1; i++) {
      if (!cur) throw new RangeError('Index out of bounds');
      cur = cur.next;
    }
    node.next = cur.next;
    cur.next = node;
    if (!node.next) this.tail = node;
    this.size++;
  }

  toArray() {
    const out = [];
    let cur = this.head;
    while (cur) { out.push(cur.value); cur = cur.next; }
    return out;
  }
}

const list = new LinkedList();
list.append(1);
list.append(3);
list.insertAt(1, 2);
list.prepend(0);
console.log(list.toArray()); // [0, 1, 2, 3]

// Big-O comparison — Array vs Linked List
//
// Operation           | Dynamic Array | Singly Linked  | Doubly Linked
// --------------------|---------------|----------------|---------------
// Access by index     | O(1)          | O(n)           | O(n)
// Insert at front     | O(n)          | O(1)           | O(1)
// Insert at back      | O(1) amort.   | O(1)*          | O(1)*
// Insert in middle    | O(n)          | O(n)           | O(n)
// Delete by reference | O(n)          | O(n)           | O(1)**
// Memory overhead     | low + slack   | +1 ptr/node    | +2 ptrs/node
//
// * O(1) with tail pointer
// ** O(1) because prev pointer skips predecessor traversal

